#!/usr/bin/env node
// Generate docs/privacy/ropa.md, processors-register.md and retention-schedule.md from
// docs/privacy/data_inventory.yaml (spec B1, T6). Deterministic: no clock, no network.
//
// Usage: node tooling/privacy/generate-ropa.mjs [--inventory <file>] [--out <dir>] [--check]
//   --check  write nothing, exit 1 if any generated file differs from what is on disk (for CI).
import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parse } from 'yaml';
import { validateInventory } from './inventory-schema.mjs';

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = resolve(here, '..', '..');

const BANNER = (file) =>
  `<!-- GENERATED by tooling/privacy/generate-ropa.mjs from docs/privacy/data_inventory.yaml. Do not edit by hand. (${file}) -->`;

const STATUS_NOTE = (inv) =>
  `> **Status: ${inv.status}.** Last reviewed ${inv.last_reviewed}. This is an engineering draft, not legal advice. ` +
  'Every lawful basis, retention period and residency value is a proposal until counsel and the DPO review it. ' +
  'Entries marked **VERIFY BEFORE LAUNCH** are tracked in the verify register. ' +
  'No real personal data may be processed until ADR-0002 is accepted.';

const uniq = (xs) => [...new Set(xs)];
const sortStr = (xs) => [...xs].sort((a, b) => a.localeCompare(b));
const esc = (s) => String(s).replace(/\|/g, '\\|').replace(/\n/g, ' ');
const code = (xs) => (xs.length === 0 ? 'none' : xs.map((x) => `\`${x}\``).join(', '));

function periodText(p) {
  if (p === null) return 'event-driven (no fixed period)';
  return `${p.value} ${p.unit}`;
}

function purposeSection(inv, resolved, pid) {
  const p = inv.purposes[pid];
  const rows = resolved.filter((r) => (r.purpose ?? []).includes(pid));
  if (rows.length === 0) return null;
  const tables = sortStr(uniq(rows.map((r) => r.table)));
  const subjects = sortStr(uniq(rows.flatMap((r) => r.data_subjects)));
  const bases = sortStr(uniq(rows.map((r) => r.lawful_basis)));
  const consents = sortStr(uniq(rows.map((r) => r.consent_purpose).filter(Boolean)));
  const classes = sortStr(uniq(rows.map((r) => r.pii_class)));
  const procs = sortStr(uniq(rows.flatMap((r) => r.processors ?? [])));
  const rets = sortStr(uniq(rows.map((r) => r.retention)));
  const resid = sortStr(uniq(rows.map((r) => r.residency)));
  const enc = sortStr(uniq(rows.map((r) => r.encryption).filter((e) => e !== 'none')));
  const verify = rows.filter((r) => r.verify).length;
  const lines = [
    `### ${p.title} (\`${pid}\`)`,
    '',
    p.description,
    '',
    `- **Data subjects:** ${code(subjects)}`,
    `- **Lawful basis:** ${code(bases)}${consents.length ? ` (consent purposes: ${code(consents)})` : ''}`,
    `- **PII classes:** ${code(classes)} across ${rows.length} fields in ${tables.length} tables`,
    `- **Tables:** ${code(tables)}`,
    `- **Recipients and processors:** ${procs.length ? procs.map((x) => `\`${x}\``).join(', ') : 'none'}`,
    `- **Retention:** ${rets.map((r) => `\`${r}\` (${periodText(inv.retention[r].period)})`).join(', ')}`,
    `- **Residency:** ${code(resid)}`,
    `- **Technical safeguards:** ${enc.length ? code(enc) : 'none beyond access control'}`,
    `- **Open verification items:** ${verify} field${verify === 1 ? '' : 's'} flagged VERIFY BEFORE LAUNCH`,
    '',
  ];
  return lines.join('\n');
}

export function renderRopa(inv, resolved) {
  const out = [];
  out.push(BANNER('ropa.md'), '');
  out.push('# Record of processing activities (RoPA)', '');
  out.push('Z-OUTLET (spec name HAUL), spec B1 and T6.', '');
  out.push(STATUS_NOTE(inv), '');
  out.push('## 1. Controller', '');
  out.push(
    '| Item | Value |',
    '|---|---|',
    '| Controller | Z-OUTLET operating entity: **not yet incorporated or named. VERIFY BEFORE LAUNCH** |',
    '| DPO | **Not yet appointed. VERIFY BEFORE LAUNCH** (admin role `dpo` exists in the spec) |',
    '| PDPC licence or registration | **Category and fee unverified. VERIFY BEFORE LAUNCH** |',
    '| Data plane location | **Undecided** (ADR-0002 not accepted) |',
    '',
  );

  const byClass = { P0: 0, P1: 0, P2: 0, P3: 0 };
  for (const r of resolved) byClass[r.pii_class] += 1;
  out.push('## 2. Inventory summary', '');
  out.push(
    '| Measure | Count |',
    '|---|---|',
    `| Tables | ${inv.tables.length} |`,
    `| Fields | ${resolved.length} |`,
    `| P0 public | ${byClass.P0} |`,
    `| P1 internal | ${byClass.P1} |`,
    `| P2 personal | ${byClass.P2} |`,
    `| P3 sensitive | ${byClass.P3} |`,
    `| Fields flagged VERIFY BEFORE LAUNCH | ${resolved.filter((r) => r.verify).length} |`,
    `| Tables derived from spec prose, not named columns | ${inv.tables.filter((t) => t.source === 'derived').length} |`,
    `| Processors in register | ${Object.keys(inv.processors).length} |`,
    `| Processors with DPA status other than signed | ${Object.values(inv.processors).filter((p) => p.dpa_status !== 'signed').length} |`,
    '',
  );

  out.push('## 3. Processing activities by purpose', '');
  for (const pid of Object.keys(inv.purposes).sort()) {
    const sec = purposeSection(inv, resolved, pid);
    if (sec) out.push(sec);
  }

  out.push('## 4. Consent purposes', '');
  out.push('| Consent purpose | Fields gated by it | Tables |', '|---|---|---|');
  for (const c of inv.consent_purposes) {
    const rows = resolved.filter((r) => r.consent_purpose === c);
    out.push(`| \`${c}\` | ${rows.length} | ${code(sortStr(uniq(rows.map((r) => r.table))))} |`);
  }
  out.push('');

  out.push('## 5. Special handling', '');
  const p3 = resolved.filter((r) => r.pii_class === 'P3');
  out.push(
    `P3 fields (${p3.length}) must be field-encrypted, hashed, tokenized or kept on device, must stay in country, and never go to an external LLM (spec T12).`,
    '',
    '| Field | Encryption | Residency | Seller visibility |',
    '|---|---|---|---|',
  );
  for (const r of p3) out.push(`| \`${r.path}\` | ${r.encryption} | ${r.residency} | ${r.seller_visibility} |`);
  out.push('');
  const budget = inv.tables.filter((t) => (t.forbidden_importers ?? []).length > 0);
  if (budget.length) {
    out.push('Tables closed to promotions and ads (budget insights, spec section 12):', '');
    for (const t of budget) out.push(`- \`${t.name}\` forbids importers ${code(t.forbidden_importers)}`);
    out.push('');
  }

  out.push('## 6. Field-level detail', '');
  for (const t of inv.tables) {
    const rows = resolved.filter((r) => r.table === t.name);
    out.push(`### \`${t.name}\``, '');
    out.push(
      `Source: ${t.source === 'spec_named' ? 'named in the spec' : 'derived (confirm when the ERD is final)'} (${esc(t.spec_ref)}). ` +
        `Storage: ${t.storage}. Data subjects: ${code(t.data_subjects)}.`,
      '',
    );
    out.push(
      '| Field | Class | Purpose | Basis | Retention | Processors | Residency | Encryption | Seller | On erasure | Verify |',
      '|---|---|---|---|---|---|---|---|---|---|---|',
    );
    for (const r of rows) {
      const basis = r.consent_purpose ? `${r.lawful_basis} (${r.consent_purpose})` : r.lawful_basis;
      out.push(
        `| \`${r.name}\` | ${r.pii_class} | ${esc((r.purpose ?? []).join(', '))} | ${esc(basis)} | ${r.retention} | ${esc((r.processors ?? []).join(', ') || 'none')} | ${r.residency} | ${r.encryption} | ${r.seller_visibility} | ${r.on_erasure} | ${r.verify ? 'VERIFY' : ''} |`,
      );
    }
    out.push('');
  }
  return out.join('\n');
}

export function renderProcessors(inv, resolved) {
  const out = [BANNER('processors-register.md'), '', '# Processors register', ''];
  out.push(STATUS_NOTE(inv), '');
  out.push(
    'Every processor below has **DPA status unknown unless stated**. No contract exists. Candidates are names taken from the spec or common in the Egyptian market, not selections. ' +
      'A role shown as `unknown` or an assumed role must be confirmed by counsel (processor, independent controller or joint controller).',
    '',
  );
  out.push(
    '| Id | Category | Candidates | Role | Location | DPA | Sub-processors | TIA | Contract | Fields served |',
    '|---|---|---|---|---|---|---|---|---|---|',
  );
  for (const [id, p] of Object.entries(inv.processors)) {
    const n = resolved.filter((r) => (r.processors ?? []).includes(id)).length;
    out.push(
      `| \`${id}\` | ${p.category} | ${esc(p.candidates.join('; ') || 'none')} | ${p.role} | ${esc(p.location)} | ${p.dpa_status} | ${p.sub_processors} | ${p.transfer_tia} | ${p.contract_status} | ${n} |`,
    );
  }
  out.push('');
  out.push('## Data each processor can see', '');
  for (const [id, p] of Object.entries(inv.processors)) {
    const rows = resolved.filter((r) => (r.processors ?? []).includes(id));
    const classes = sortStr(uniq(rows.map((r) => r.pii_class)));
    const tables = sortStr(uniq(rows.map((r) => r.table)));
    out.push(`### ${p.name} (\`${id}\`)`, '');
    out.push(`- **Spec reference:** ${p.spec_ref}`);
    out.push(`- **Highest class handled:** ${classes.length ? classes[classes.length - 1] : 'none referenced'}`);
    out.push(`- **Tables:** ${tables.length ? code(tables) : 'none referenced yet'}`);
    if (p.note) out.push(`- **Note:** ${p.note}`);
    out.push(`- **Open:** DPA, sub-processor list, transfer assessment (see [TIA template](tia-template.md)). **VERIFY BEFORE LAUNCH**`, '');
  }
  return out.join('\n');
}

export function renderRetention(inv, resolved) {
  const out = [BANNER('retention-schedule.md'), '', '# Retention schedule', ''];
  out.push(STATUS_NOTE(inv), '');
  out.push(
    'Source `spec` means the period comes from spec B1. Source `proposed` means engineering suggested it and it is **not** a legal position. ' +
      'Each rule maps to a nightly purge job with a metric (spec B1).',
    '',
  );
  out.push(
    '| Rule | Period | Starts at | Then | Purge job | Metric | Source | Fields | Verify |',
    '|---|---|---|---|---|---|---|---|---|',
  );
  for (const [id, r] of Object.entries(inv.retention)) {
    const n = resolved.filter((f) => f.retention === id).length;
    out.push(
      `| \`${id}\`<br>${esc(r.description)} | ${periodText(r.period)} | ${r.trigger} | ${r.after} | \`${r.purge_job}\` | \`${r.purge_metric}\` | ${r.source} | ${n} | ${r.verify ? 'VERIFY' : ''} |`,
    );
  }
  out.push('');
  return out.join('\n');
}

export function renderAll(inv, resolved) {
  return {
    'ropa.md': renderRopa(inv, resolved),
    'processors-register.md': renderProcessors(inv, resolved),
    'retention-schedule.md': renderRetention(inv, resolved),
  };
}

function parseArgs(argv) {
  const opts = {
    inventory: join(repoRoot, 'docs', 'privacy', 'data_inventory.yaml'),
    out: join(repoRoot, 'docs', 'privacy'),
    check: false,
  };
  for (let i = 0; i < argv.length; i += 1) {
    const a = argv[i];
    if (a === '--inventory') opts.inventory = resolve(argv[++i]);
    else if (a === '--out') opts.out = resolve(argv[++i]);
    else if (a === '--check') opts.check = true;
    else throw new Error(`unknown argument ${a}`);
  }
  return opts;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const opts = parseArgs(process.argv.slice(2));
  const result = validateInventory(parse(readFileSync(opts.inventory, 'utf8')));
  if (!result.ok) {
    for (const e of result.errors) console.error(`error: ${e}`);
    console.error('inventory is invalid, nothing generated');
    process.exit(1);
  }
  const files = renderAll(result.inventory, result.resolved);
  let stale = 0;
  if (!opts.check) mkdirSync(opts.out, { recursive: true });
  for (const [name, content] of Object.entries(files)) {
    const target = join(opts.out, name);
    const body = `${content}\n`;
    if (opts.check) {
      const current = existsSync(target) ? readFileSync(target, 'utf8') : '';
      if (current !== body) {
        console.error(`stale: ${target}`);
        stale += 1;
      }
    } else {
      writeFileSync(target, body);
      console.log(`wrote ${target}`);
    }
  }
  process.exit(stale > 0 ? 1 : 0);
}
